STATIC
UNIT_TEST_STATUS
EFIAPI
TestSetup (
  IN UNIT_TEST_CONTEXT  Context
  )
{
  UefiBootServicesTableInit ();
  NvidiaSetDriverHealthStatus (EfiDriverHealthStatusHealthy);
  return UNIT_TEST_PASSED;
}

