extern CHAR8  ssdtpcietemplate_aml_code[];

#define DSD_EXTERNAL_FACING_PORT_GUID \
(GUID){0xEFCC06CC, 0x73AC, 0x4BC3, {0xBF, 0xF0, 0x76, 0x14, 0x38, 0x07, 0xC3, 0x89}}

#define NV_THERM_I2CS_SCRATCH  0x200bc

STATIC
EFI_STATUS
EFIAPI
GeneratePciDSDForExtPort (
  IN       CONST CM_ARCH_COMMON_PCI_CONFIG_SPACE_INFO  *PciInfo,
  IN  OUT        AML_OBJECT_NODE_HANDLE                RpNode,
  IN             UINT32                                Uid
  )
{
  EFI_STATUS              Status;
  AML_OBJECT_NODE_HANDLE  DsdNode;
  AML_OBJECT_NODE_HANDLE  DsdPkgNode;
  EFI_HANDLE              *Handles = NULL;
  UINTN                   NumberOfHandles;
  UINTN                   CurrentHandle;
  BOOLEAN                 IsExternalFacingPort;
  EFI_GUID                ExtPortGUID = DSD_EXTERNAL_FACING_PORT_GUID;

  Status = gBS->LocateHandleBuffer (
                  ByProtocol,
                  &gNVIDIAPciRootBridgeConfigurationIoProtocolGuid,
                  NULL,
                  &NumberOfHandles,
                  &Handles
                  );
  if (EFI_ERROR (Status)) {
    DEBUG ((DEBUG_ERROR, "%a: Failed to locate host bridge protocols, %r.\r\n", __FUNCTION__, Status));
    goto exit_handler;
  }

  for (CurrentHandle = 0; CurrentHandle < NumberOfHandles; CurrentHandle++) {
    NVIDIA_PCI_ROOT_BRIDGE_CONFIGURATION_IO_PROTOCOL  *RootBridgeCfgIo = NULL;
    Status = gBS->HandleProtocol (
                    Handles[CurrentHandle],
                    &gNVIDIAPciRootBridgeConfigurationIoProtocolGuid,
                    (VOID **)&RootBridgeCfgIo
                    );
    if (EFI_ERROR (Status)) {
      DEBUG ((
        DEBUG_ERROR,
        "%a: Failed to get protocol for handle %p, %r.\r\n",
        __FUNCTION__,
        Handles[CurrentHandle],
        Status
        ));
      goto exit_handler;
    }

    if (PciInfo->PciSegmentGroupNumber != RootBridgeCfgIo->SegmentNumber) {
      continue;
    }

    IsExternalFacingPort = RootBridgeCfgIo->IsExternalFacingPort;
  }

  if (!IsExternalFacingPort) {
    Status = EFI_SUCCESS;
    goto exit_handler;
  }

  Status = AmlCodeGenNamePackage ("_DSD", NULL, &DsdNode);
  if (EFI_ERROR (Status)) {
    ASSERT (0);
    goto exit_handler;
  }

  Status = AmlAddDeviceDataDescriptorPackage (
             &ExtPortGUID,
             DsdNode,
             &DsdPkgNode
             );
  if (EFI_ERROR (Status)) {
    ASSERT (0);
    goto exit_handler;
  }

  Status = AmlAddNameIntegerPackage ("ExternalFacingPort", 1, DsdPkgNode);
  if (EFI_ERROR (Status)) {
    ASSERT (0);
    goto exit_handler;
  }

  Status = AmlAddNameIntegerPackage ("UID", Uid, DsdPkgNode);
  if (EFI_ERROR (Status)) {
    ASSERT (0);
    goto exit_handler;
  }

  Status = AmlAttachNode (RpNode, DsdNode);
  if (EFI_ERROR (Status)) {
    ASSERT_EFI_ERROR (Status);
    goto exit_handler;
  }

exit_handler:
  if (Handles != NULL) {
    FreePool (Handles);
  }

  return Status;
}

STATIC
EFI_STATUS
EFIAPI
UpdateSharedNSMemAddr (
  IN       CONST CM_ARCH_COMMON_PCI_CONFIG_SPACE_INFO  *PciInfo,
  IN  OUT        AML_OBJECT_NODE_HANDLE                RpNode,
  IN             UINT32                                Socket,
  IN             UINT32                                Instance
  )
{
  EFI_STATUS                   Status;
  RAS_PCIE_DPC_COMM_BUF_INFO   *DpcCommBuf = NULL;
  RAS_FW_PCIE_DPC_COMM_STRUCT  *DpcComm    = NULL;
  AML_OBJECT_NODE_HANDLE       AddrNode;

  Status = gBS->LocateProtocol (
                  &gNVIDIARasNsCommPcieDpcDataProtocolGuid,
                  NULL,
                  (VOID **)&DpcCommBuf
                  );
  if (EFI_ERROR (Status)) {
    DEBUG ((
      DEBUG_ERROR,
      "%a: Couldn't get gNVIDIARasNsCommPcieDpcDataProtocolGuid protocol: %r\n",
      __FUNCTION__,
      Status
      ));
  }

  if (DpcCommBuf == NULL) {
    // Protocol installed NULL interface. Skip using it.
    return EFI_SUCCESS;
  }

  DpcComm = (RAS_FW_PCIE_DPC_COMM_STRUCT *)DpcCommBuf->PcieBase;
  DEBUG ((DEBUG_VERBOSE, "%a: Socket = %u, Instance = %u\r\n", __FUNCTION__, Socket, Instance));

  Status = AmlFindNode (RpNode, "ADDR", &AddrNode);
  if (EFI_ERROR (Status)) {
    return Status;
  }

  Status = AmlNameOpUpdateInteger (AddrNode, (UINT64)(&(DpcComm->PcieDpcInfo[Socket][Instance])));
  if (EFI_ERROR (Status)) {
    return Status;
  }

  return Status;
}

STATIC
EFI_STATUS
EFIAPI
UpdateLICAddr (
  IN       CONST CM_ARCH_COMMON_PCI_CONFIG_SPACE_INFO  *PciInfo,
  IN  OUT        AML_OBJECT_NODE_HANDLE                Node,
  IN             UINT64                                Socket,
  IN             EFI_PHYSICAL_ADDRESS                  Base
  )
{
  EFI_STATUS              Status;
  AML_OBJECT_NODE_HANDLE  LicaNode;
  EFI_PHYSICAL_ADDRESS    Address;

  Status = AmlFindNode (Node, "LICA", &LicaNode);
  if (EFI_ERROR (Status)) {
    return Status;
  }

  Address = Base | (Socket << TH500_SOCKET_SHFT);

  Status = AmlNameOpUpdateInteger (LicaNode, Address);
  if (EFI_ERROR (Status)) {
    return Status;
  }

  return Status;
}

STATIC
EFI_STATUS
EFIAPI
DisableGFWBootCompletePoll (
  IN       CONST CM_ARCH_COMMON_PCI_CONFIG_SPACE_INFO  *PciInfo,
  IN  OUT        AML_OBJECT_NODE_HANDLE                Node
  )
{
  EFI_STATUS              Status;
  AML_OBJECT_NODE_HANDLE  GfbpNode;

  Status = AmlFindNode (Node, "GFBP", &GfbpNode);
  if (EFI_ERROR (Status)) {
    return Status;
  }

  Status = AmlNameOpUpdateInteger (GfbpNode, 0);
  if (EFI_ERROR (Status)) {
    return Status;
  }

  return Status;
}

STATIC
EFI_STATUS
EFIAPI
UpdateFSPBootAddr (
  IN       CONST CM_ARCH_COMMON_PCI_CONFIG_SPACE_INFO  *PciInfo,
  IN  OUT        AML_OBJECT_NODE_HANDLE                Node
  )
{
  EFI_STATUS              Status;
  AML_OBJECT_NODE_HANDLE  FspaNode;
  EFI_PHYSICAL_ADDRESS    Address;
  CHAR8                   NodeName[] = "FSPA";

  if (PciInfo->BaseAddress < TH500_VDM_SIZE) {
    return EFI_INVALID_PARAMETER;
  }

  Status = AmlFindNode (Node, NodeName, &FspaNode);
  if (EFI_ERROR (Status)) {
    return Status;
  }

  Address = PciInfo->BaseAddress - TH500_VDM_SIZE + NV_THERM_I2CS_SCRATCH;
  Status  = AmlNameOpUpdateInteger (FspaNode, Address);
  return Status;
}

STATIC
EFI_STATUS
EFIAPI
UpdateLOC (
  IN  OUT        AML_OBJECT_NODE_HANDLE  Node,
  IN             UINT8                   SocketId,
  IN             UINT8                   ControllerId
  )
{
  EFI_STATUS              Status;
  AML_OBJECT_NODE_HANDLE  LocNode;

  Status = AmlFindNode (Node, "_LOC", &LocNode);
  if (EFI_ERROR (Status)) {
    return Status;
  }

  Status = AmlNameOpUpdateInteger (LocNode, (SocketId << 4) | ControllerId);
  if (EFI_ERROR (Status)) {
    return Status;
  }

  return Status;
}

/** Generate Pci slots devices.

  PCI Firmware Specification - Revision 3.3,
  s4.8 "Generic ACPI PCI Slot Description" requests to describe the PCI slot
  used. It should be possible to enumerate them, but this is additional
  information.

  @param [in]       PciInfo       Pci device information.
  @param [in]       MappingTable  The mapping table structure.
  @param [in]       Uid           Unique Id of the Pci device.
  @param [in, out]  PciNode       Pci node to amend.

  @retval EFI_SUCCESS            Success.
  @retval EFI_INVALID_PARAMETER  Invalid parameter.
  @retval EFI_OUT_OF_RESOURCES   Failed to allocate memory.
**/
EFI_STATUS
EFIAPI
GeneratePciSlots (
  IN      CONST CM_ARCH_COMMON_PCI_CONFIG_SPACE_INFO  *PciInfo,
  IN      CONST MAPPING_TABLE                         *MappingTable,
  IN            UINT32                                Uid,
  IN  OUT       AML_OBJECT_NODE_HANDLE                PciNode
  )
{
  EFI_STATUS                              Status;
  EFI_STATUS                              Status1;
  EFI_ACPI_DESCRIPTION_HEADER             *SsdtPcieTemplate;
  AML_ROOT_NODE_HANDLE                    TemplateRoot;
  AML_OBJECT_NODE_HANDLE                  GpuNode;
  AML_OBJECT_NODE_HANDLE                  DsdNode;
  AML_OBJECT_NODE_HANDLE                  RpNode;
  EFI_HANDLE                              *HandleBuffer = NULL;
  UINTN                                   NumberOfHandles;
  UINTN                                   HandleIndex;
  EFI_PCI_IO_PROTOCOL                     *PciIo;
  UINTN                                   SegmentNumber;
  UINTN                                   BusNumber;
  UINTN                                   DeviceNumber;
  UINTN                                   FunctionNumber;
  NVIDIA_GPU_DSD_AML_GENERATION_PROTOCOL  *GpuDsdGeneration;
  PCI_DEVICE_PATH                         *PciDevicePathNode;
  EFI_DEVICE_PATH_PROTOCOL                *DevicePath;
  AML_OBJECT_NODE_HANDLE                  CurrentNode;
  AML_OBJECT_NODE_HANDLE                  SwitchNode;
  CHAR8                                   SwitchName[5];
  UINT8                                   SwitchNumber;
  BOOLEAN                                 GpuNodeIsDetached;
  EFI_HANDLE                              *Handles = NULL;
  UINTN                                   CurrentHandle;
  UINT32                                  SocketID     = 0xFFFFFFFF;
  UINT32                                  ControllerID = 0xFFFFFFFF;
  UINT32                                  RpID         = 0xFFFFFFFF;
  UINTN                                   ChipId;
  CHAR8                                   PCIeAslName[AML_NAME_SEG_SIZE + 1];

  ChipId = TegraGetChipID ();

  ASSERT (
    PciNode !=  NULL
    );

  // Parse the Ssdt Pci Osc Template.
  SsdtPcieTemplate = (EFI_ACPI_DESCRIPTION_HEADER *)
                     ssdtpcietemplate_aml_code;

  GpuNodeIsDetached = FALSE;
  GpuNode           = NULL;
  TemplateRoot      = NULL;
  Status            = AmlParseDefinitionBlock (
                        SsdtPcieTemplate,
                        &TemplateRoot
                        );
  if (EFI_ERROR (Status)) {
    DEBUG ((
      DEBUG_ERROR,
      "ERROR: SSDT-PCI: Failed to parse SSDT PCI Template."
      " Status = %r\n",
      Status
      ));
    return Status;
  }

  Status = AmlFindNode (TemplateRoot, "\\RP00", &RpNode);
  if (EFI_ERROR (Status)) {
    goto error_handler;
  }

  Status = AmlDetachNode (RpNode);
  if (EFI_ERROR (Status)) {
    goto error_handler;
  }

  Status = AmlAttachNode (PciNode, RpNode);
  if (EFI_ERROR (Status)) {
    // Free the detached node.
    AmlDeleteTree (RpNode);
    goto error_handler;
  }

  Status = gBS->LocateHandleBuffer (
                  ByProtocol,
                  &gNVIDIAPciRootBridgeConfigurationIoProtocolGuid,
                  NULL,
                  &NumberOfHandles,
                  &Handles
                  );
  if (EFI_ERROR (Status)) {
    DEBUG ((DEBUG_ERROR, "%a: Failed to locate host bridge protocols, %r.\r\n", __FUNCTION__, Status));
    goto error_handler;
  }

  for (CurrentHandle = 0; CurrentHandle < NumberOfHandles; CurrentHandle++) {
    NVIDIA_PCI_ROOT_BRIDGE_CONFIGURATION_IO_PROTOCOL  *RootBridgeCfgIo = NULL;
    Status = gBS->HandleProtocol (
                    Handles[CurrentHandle],
                    &gNVIDIAPciRootBridgeConfigurationIoProtocolGuid,
                    (VOID **)&RootBridgeCfgIo
                    );
    if (EFI_ERROR (Status)) {
      DEBUG ((
        DEBUG_ERROR,
        "%a: Failed to get protocol for handle %p, %r.\r\n",
        __FUNCTION__,
        Handles[CurrentHandle],
        Status
        ));
      goto error_handler;
    }

    if (ChipId == T410_CHIP_ID) {
      if ((PciInfo->PciSegmentGroupNumber == RootBridgeCfgIo->SegmentNumber) &&
          (PciInfo->StartBusNumber == RootBridgeCfgIo->MinBusNumber) &&
          (PciInfo->EndBusNumber == RootBridgeCfgIo->MaxBusNumber))
      {
        SocketID     = RootBridgeCfgIo->SocketID;
        ControllerID = RootBridgeCfgIo->ControllerID;
        RpID         = RootBridgeCfgIo->RpID;
        DEBUG ((
          DEBUG_INFO,
          "%a: Match found Skt = 0x%X, Ctrl = 0x%X, Rp = 0x%X\r\n",
          __FUNCTION__,
          SocketID,
          ControllerID,
          RpID
          ));
        break;
      }
    } else {
      if (PciInfo->PciSegmentGroupNumber == RootBridgeCfgIo->SegmentNumber) {
        SocketID     = RootBridgeCfgIo->SocketID;
        ControllerID = RootBridgeCfgIo->ControllerID;
        break;
      }
    }
  }

  if (ChipId == T410_CHIP_ID) {
    if ((SocketID == 0xFFFFFFFF) && (ControllerID == 0xFFFFFFFF) && (RpID == 0xFFFFFFFF)) {
      DEBUG ((
        DEBUG_ERROR,
        "%a: Failed to get SocketID & ControllerID for the Segment %x.\r\n",
        __FUNCTION__,
        PciInfo->PciSegmentGroupNumber
        ));
      goto error_handler;
    }
  } else {
    if ((SocketID == 0xFFFFFFFF) && (ControllerID == 0xFFFFFFFF)) {
      DEBUG ((
        DEBUG_ERROR,
        "%a: Failed to get SocketID & ControllerID for the Segment %x.\r\n",
        __FUNCTION__,
        PciInfo->PciSegmentGroupNumber
        ));
      goto error_handler;
    }
  }

  if (ChipId == T410_CHIP_ID) {
    /*
     * Change the name of the PCIe SSDT node to the following format
     * Pxyz where x=Socket ID, y=Controller ID, z=Rootport ID
     */
    CopyMem (PCIeAslName, "Pxyz", AML_NAME_SEG_SIZE + 1);
    PCIeAslName[AML_NAME_SEG_SIZE - 1] = AsciiFromHex (RpID & 0xF);
    PCIeAslName[AML_NAME_SEG_SIZE - 2] = AsciiFromHex (ControllerID & 0xF);
    PCIeAslName[AML_NAME_SEG_SIZE - 3] = AsciiFromHex (SocketID & 0xF);
  } else {
    /*
     * Change the name of the PCIe SSDT node to the following format
     * PCxy where x=Socket ID and y=Controller ID
     */
    CopyMem (PCIeAslName, "PCIx", AML_NAME_SEG_SIZE + 1);
    PCIeAslName[AML_NAME_SEG_SIZE - 1] = AsciiFromHex (ControllerID & 0xF);
    if (SocketID > 0) {
      PCIeAslName[AML_NAME_SEG_SIZE - 2] = AsciiFromHex (SocketID & 0xF);
    }
  }

  Status = AmlDeviceOpUpdateName (PciNode, PCIeAslName);
  if (EFI_ERROR (Status)) {
    goto error_handler;
  }

  /*
   * Using the Socket-ID as the Proximity Domain ID.
   */
  Status = AmlCodeGenNameInteger (
             "_PXM",
             SocketID & 0xF,
             PciNode,
             NULL
             );
  if (EFI_ERROR (Status)) {
    ASSERT (0);
    return Status;
  }

  Status = UpdateLOC (RpNode, SocketID, ControllerID);
  if (EFI_ERROR (Status)) {
    goto error_handler;
  }

  Status = GeneratePciDSDForExtPort (PciInfo, RpNode, Uid);
  if (EFI_ERROR (Status)) {
    goto error_handler;
  }

  Status = UpdateSharedNSMemAddr (PciInfo, RpNode, SocketID, ControllerID);
  if (EFI_ERROR (Status)) {
    goto error_handler;
  }

  Status1 = gBS->LocateHandleBuffer (
                   ByProtocol,
                   &gEfiNVIDIAGpuDSDAMLGenerationProtocolGuid,
                   NULL,
                   &NumberOfHandles,
                   &HandleBuffer
                   );
  DEBUG ((
    DEBUG_ERROR,
    "DEBUG: SSDT-PCI: GpuDSDAMLGeneration Proocol(s) [handles:%u handle buffer:%p]"      " Status = %r\n",
    NumberOfHandles,
    HandleBuffer,
    Status1
    ));

  if (!EFI_ERROR (Status1)) {
    for (HandleIndex = 0; HandleIndex < NumberOfHandles; HandleIndex++) {
      Status1 = gBS->HandleProtocol (
                       HandleBuffer[HandleIndex],
                       &gEfiPciIoProtocolGuid,
                       (VOID **)&PciIo
                       );
      if (EFI_ERROR (Status1)) {
        continue;
      }

      Status1 = PciIo->GetLocation (PciIo, &SegmentNumber, &BusNumber, &DeviceNumber, &FunctionNumber);
      if (EFI_ERROR (Status1)) {
        continue;
      }

      if (SegmentNumber != PciInfo->PciSegmentGroupNumber) {
        continue;
      } else {
        if ((BusNumber < PciInfo->StartBusNumber) || (BusNumber > PciInfo->EndBusNumber)) {
          continue;
        }
      }

      Status = gBS->HandleProtocol (
                      HandleBuffer[HandleIndex],
                      &gEfiNVIDIAGpuDSDAMLGenerationProtocolGuid,
                      (VOID **)&GpuDsdGeneration
                      );
      DEBUG ((
        DEBUG_ERROR,
        "DEBUG: SSDT-PCI: GpuDSDAMLGeneration Proocol(s) [HandleIndex:%u Protocol:%p]"      " Status = %r\n",
        HandleIndex,
        GpuDsdGeneration,
        Status1
        ));

      if (EFI_ERROR (Status)) {
        ASSERT_EFI_ERROR (Status);
        goto error_handler;
      }

      Status = AmlFindNode (TemplateRoot, "\\GPU0", &GpuNode);
      if (EFI_ERROR (Status)) {
        goto error_handler;
      }

      Status = AmlDetachNode (GpuNode);
      if (EFI_ERROR (Status)) {
        goto error_handler;
      }

      GpuNodeIsDetached = TRUE;
      Status            = GpuDsdGeneration->GetDsdNode (GpuDsdGeneration, &DsdNode);
      if (EFI_ERROR (Status)) {
        ASSERT_EFI_ERROR (Status);
      } else {
        Status = AmlAttachNode (GpuNode, DsdNode);
        if (EFI_ERROR (Status)) {
          goto error_handler;
        }
      }

      Status = gBS->HandleProtocol (
                      HandleBuffer[HandleIndex],
                      &gEfiDevicePathProtocolGuid,
                      (VOID **)&DevicePath
                      );
      if (EFI_ERROR (Status)) {
        DEBUG ((DEBUG_ERROR, "%a: no GPU device path: %r\n", __FUNCTION__, Status));
        goto error_handler;
      }

      CurrentNode  = NULL;
      SwitchNumber = 0;
      while (!IsDevicePathEnd (DevicePath)) {
        DEBUG ((DEBUG_INFO, "%a: type=0x%x subtype=0x%x\n", __FUNCTION__, DevicePath->Type, DevicePath->SubType));

        if ((DevicePath->Type == HARDWARE_DEVICE_PATH) &&
            (DevicePath->SubType == HW_PCI_DP))
        {
          PciDevicePathNode = (PCI_DEVICE_PATH *)DevicePath;
          DEBUG ((DEBUG_INFO, "%a: Pci Dev=0x%x Func=0x%x \n", __FUNCTION__, PciDevicePathNode->Device, PciDevicePathNode->Function));

          // First PCI device in path is RP node
          // Last PCI device in path is the GPU node
          // Any additional PCI devices between first and last are switch nodes
          if (IsDevicePathEnd (NextDevicePathNode (DevicePath))) {
            DevicePath = NextDevicePathNode (DevicePath);
            continue;
          }

          if (CurrentNode == NULL) {
            CurrentNode = RpNode;
          } else {
            AsciiSPrint (SwitchName, sizeof (SwitchName), "SW%02x", SwitchNumber);
            Status = AmlCodeGenDevice (SwitchName, CurrentNode, &SwitchNode);
            if (EFI_ERROR (Status)) {
              goto error_handler;
            }

            CurrentNode = SwitchNode;
            Status      = AmlCodeGenNameInteger (
                            "_ADR",
                            (PciDevicePathNode->Device << 16) | PciDevicePathNode->Function,
                            SwitchNode,
                            NULL
                            );
            if (EFI_ERROR (Status)) {
              goto error_handler;
            }

            DEBUG ((DEBUG_INFO, "%a: inserted %a\n", __FUNCTION__, SwitchName));

            SwitchNumber++;
          }
        }

        DevicePath = NextDevicePathNode (DevicePath);
      }

      if (CurrentNode == NULL) {
        DEBUG ((DEBUG_ERROR, "%a: bad DP\n", __FUNCTION__));
        goto error_handler;
      }

      Status = AmlAttachNode (CurrentNode, GpuNode);
      if (EFI_ERROR (Status)) {
        goto error_handler;
      }

      GpuNodeIsDetached = FALSE;

      Status = UpdateLICAddr (PciInfo, GpuNode, SocketID, TH500_SW_IO1_BASE_SOCKET_0);
      if (EFI_ERROR (Status)) {
        goto error_handler;
      }

      if (GpuDsdGeneration->GpuFamily != NVIDIA_GPU_HOPPER) {
        Status = DisableGFWBootCompletePoll (PciInfo, GpuNode);
        if (EFI_ERROR (Status)) {
          goto error_handler;
        }
      }

      Status = UpdateFSPBootAddr (PciInfo, GpuNode);
      if (EFI_ERROR (Status)) {
        goto error_handler;
      }

      break;
    }

    FreePool (HandleBuffer);
    HandleBuffer = NULL;
  }

error_handler:
  // Cleanup
  if (GpuNodeIsDetached) {
    AmlDeleteTree (GpuNode);
  }

  if (HandleBuffer != NULL) {
    FreePool (HandleBuffer);
  }

  if (Handles != NULL) {
    FreePool (Handles);
  }

  Status1 = AmlDeleteTree (TemplateRoot);
  if (EFI_ERROR (Status1)) {
    DEBUG ((
      DEBUG_ERROR,
      "ERROR: SSDT-PCI: Failed to cleanup AML tree."
      " Status = %r\n",
      Status1
      ));
    // If Status was success but we failed to delete the AML Tree
    // return Status1 else return the original error code, i.e. Status.
    if (!EFI_ERROR (Status)) {
      return Status1;
    }
  }

  return Status;
}

/** Add an _OSC template method to the PciNode.

  The _OSC method is provided as an AML blob. The blob is
  parsed and attached at the end of the PciNode list of variable elements.

  @param [in]       PciInfo     Pci device information.
  @param [in, out]  PciNode     Pci node to amend.

  @retval EFI_SUCCESS             The function completed successfully.
  @retval EFI_INVALID_PARAMETER   Invalid parameter.
  @retval EFI_OUT_OF_RESOURCES    Could not allocate memory.
**/
EFI_STATUS
EFIAPI
AddOscMethod (
  IN      CONST CM_ARCH_COMMON_PCI_CONFIG_SPACE_INFO  *PciInfo,
  IN  OUT   AML_OBJECT_NODE_HANDLE                    PciNode
  )
{
  EFI_STATUS                   Status;
  EFI_STATUS                   Status1;
  EFI_ACPI_DESCRIPTION_HEADER  *SsdtPcieOscTemplate;
  AML_ROOT_NODE_HANDLE         OscTemplateRoot;
  AML_OBJECT_NODE_HANDLE       OscNode;
  EFI_HANDLE                   *Handles = NULL;
  UINTN                        NumberOfHandles;
  UINTN                        CurrentHandle;
  BOOLEAN                      OSCNodeIsDetached = FALSE;

  ASSERT (PciNode != NULL);

  // Parse the Ssdt Pci Osc Template.
  SsdtPcieOscTemplate = (EFI_ACPI_DESCRIPTION_HEADER *)
                        ssdtpcietemplate_aml_code;

  OscNode         = NULL;
  OscTemplateRoot = NULL;
  Status          = AmlParseDefinitionBlock (
                      SsdtPcieOscTemplate,
                      &OscTemplateRoot
                      );
  if (EFI_ERROR (Status)) {
    DEBUG ((
      DEBUG_ERROR,
      "ERROR: SSDT-PCI-OSC: Failed to parse SSDT PCI OSC Template."
      " Status = %r\n",
      Status
      ));
    return Status;
  }

  Status = AmlFindNode (OscTemplateRoot, "\\_OSC", &OscNode);
  if (EFI_ERROR (Status)) {
    goto error_handler;
  }

  Status = AmlDetachNode (OscNode);
  if (EFI_ERROR (Status)) {
    goto error_handler;
  }

  OSCNodeIsDetached = TRUE;
  Status            = AmlAttachNode (PciNode, OscNode);
  if (EFI_ERROR (Status)) {
    goto error_handler;
  }

  Status = gBS->LocateHandleBuffer (
                  ByProtocol,
                  &gNVIDIAPciRootBridgeConfigurationIoProtocolGuid,
                  NULL,
                  &NumberOfHandles,
                  &Handles
                  );
  if (EFI_ERROR (Status)) {
    DEBUG ((DEBUG_ERROR, "%a: Failed to locate host bridge protocols, %r.\r\n", __FUNCTION__, Status));
    goto error_handler;
  }

  for (CurrentHandle = 0; CurrentHandle < NumberOfHandles; CurrentHandle++) {
    NVIDIA_PCI_ROOT_BRIDGE_CONFIGURATION_IO_PROTOCOL  *RootBridgeCfgIo = NULL;
    Status = gBS->HandleProtocol (
                    Handles[CurrentHandle],
                    &gNVIDIAPciRootBridgeConfigurationIoProtocolGuid,
                    (VOID **)&RootBridgeCfgIo
                    );
    if (EFI_ERROR (Status)) {
      DEBUG ((
        DEBUG_ERROR,
        "%a: Failed to get protocol for handle %p, %r.\r\n",
        __FUNCTION__,
        Handles[CurrentHandle],
        Status
        ));
      goto error_handler;
    }

    if (PciInfo->PciSegmentGroupNumber == RootBridgeCfgIo->SegmentNumber) {
      AML_OBJECT_NODE_HANDLE  OSCCNode;
      Status = AmlFindNode (OscNode, "OSCC", &OSCCNode);
      if (EFI_ERROR (Status)) {
        goto error_handler;
      }

      Status = AmlNameOpUpdateInteger (OSCCNode, RootBridgeCfgIo->OSCCtrl);
      if (EFI_ERROR (Status)) {
        goto error_handler;
      }

      break;
    }
  }

  goto cleanup;

error_handler:
  if (OSCNodeIsDetached) {
    // Free the detached node.
    AmlDeleteTree (OscNode);
  }

cleanup:
  // Cleanup
  if (Handles != NULL) {
    FreePool (Handles);
  }

  Status1 = AmlDeleteTree (OscTemplateRoot);
  if (EFI_ERROR (Status1)) {
    DEBUG ((
      DEBUG_ERROR,
      "ERROR: SSDT-PCI-OSC: Failed to cleanup AML tree."
      " Status = %r\n",
      Status1
      ));
    // If Status was success but we failed to delete the AML Tree
    // return Status1 else return the original error code, i.e. Status.
    if (!EFI_ERROR (Status)) {
      return Status1;
    }
  }

  return Status;
}

